class Solution {
    public int lengthOfLIS(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        java.util.Arrays.fill(dp, 1);
        int best = 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[j] < nums[i]) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
            best = Math.max(best, dp[i]);
        }
        return best;
    }
}

class Solution {
    public int lengthOfLIS(int[] nums) {
        int[] tails = new int[nums.length];
        int size = 0;

        for (int num : nums) {
            int lo = 0;
            int hi = size;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (tails[mid] < num) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            tails[lo] = num;
            if (lo == size) {
                size++;
            }
        }
        return size;
    }
}

class Solution {
    public int lengthOfLIS(int[] nums) {
        int[][] memo = new int[nums.length][nums.length + 1];
        return dfs(nums, 0, -1, memo);
    }

    private int dfs(int[] nums, int index, int previous, int[][] memo) {
        if (index == nums.length) {
            return 0;
        }

        int memoColumn = previous + 1;
        if (memo[index][memoColumn] != 0) {
            return memo[index][memoColumn];
        }

        int skip = dfs(nums, index + 1, previous, memo);
        int take = 0;
        if (previous == -1 || nums[previous] < nums[index]) {
            take = 1 + dfs(nums, index + 1, index, memo);
        }

        memo[index][memoColumn] = Math.max(take, skip);
        return memo[index][memoColumn];
    }
}

class Solution {
    public int lengthOfLIS(int[] nums) {
        int[] values = nums.clone();
        java.util.Arrays.sort(values);
        int size = 0;
        for (int value : values) {
            if (size == 0 || values[size - 1] != value) {
                values[size++] = value;
            }
        }

        Fenwick tree = new Fenwick(size);
        int best = 0;
        for (int num : nums) {
            int rank = lowerBound(values, size, num) + 1;
            int length = tree.query(rank - 1) + 1;
            tree.update(rank, length);
            best = Math.max(best, length);
        }
        return best;
    }

    private int lowerBound(int[] values, int size, int target) {
        int lo = 0;
        int hi = size;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (values[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static class Fenwick {
        private final int[] tree;

        Fenwick(int size) {
            this.tree = new int[size + 1];
        }

        void update(int index, int value) {
            while (index < tree.length) {
                tree[index] = Math.max(tree[index], value);
                index += index & -index;
            }
        }

        int query(int index) {
            int best = 0;
            while (index > 0) {
                best = Math.max(best, tree[index]);
                index -= index & -index;
            }
            return best;
        }
    }
}

class Solution {
    public int lengthOfLIS(int[] nums) {
        int[] values = nums.clone();
        java.util.Arrays.sort(values);
        int unique = 0;
        for (int value : values) {
            if (unique == 0 || values[unique - 1] != value) {
                values[unique++] = value;
            }
        }

        SegmentTree tree = new SegmentTree(unique);
        int best = 0;
        for (int num : nums) {
            int rank = lowerBound(values, unique, num);
            int length = tree.query(0, rank - 1) + 1;
            tree.update(rank, length);
            best = Math.max(best, length);
        }
        return best;
    }

    private int lowerBound(int[] values, int size, int target) {
        int lo = 0;
        int hi = size;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (values[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static class SegmentTree {
        private final int size;
        private final int[] tree;

        SegmentTree(int count) {
            int capacity = 1;
            while (capacity < count) {
                capacity <<= 1;
            }
            this.size = capacity;
            this.tree = new int[size * 2];
        }

        void update(int index, int value) {
            int position = index + size;
            tree[position] = Math.max(tree[position], value);
            position >>= 1;
            while (position > 0) {
                tree[position] = Math.max(tree[position << 1], tree[position << 1 | 1]);
                position >>= 1;
            }
        }

        int query(int left, int right) {
            if (right < left) {
                return 0;
            }
            left += size;
            right += size;
            int best = 0;
            while (left <= right) {
                if ((left & 1) == 1) {
                    best = Math.max(best, tree[left++]);
                }
                if ((right & 1) == 0) {
                    best = Math.max(best, tree[right--]);
                }
                left >>= 1;
                right >>= 1;
            }
            return best;
        }
    }
}
